// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.Test;

class LmdbNativeRegimeTrackerTest {

	@Test
	void maintenanceStatesMapOntoTheThreePhases() {
		for (String building : new String[] { "BUILDING", "CATCHING_UP", "QUIESCING_FOR_REBUILD" }) {
			assertEquals(LmdbNativeRegimeKey.Phase.BUILDING, LmdbNativeRegimeTracker.mapPhase(building, true));
		}
		for (String warm : new String[] { "ACTIVE", "DISABLED", "EMPTY" }) {
			assertEquals(LmdbNativeRegimeKey.Phase.WARM_STABLE, LmdbNativeRegimeTracker.mapPhase(warm, true));
			assertEquals(LmdbNativeRegimeKey.Phase.TRANSITIONAL_COLD, LmdbNativeRegimeTracker.mapPhase(warm, false),
					"pending kernel compiles keep " + warm + " out of the steady regime");
		}
		for (String cold : new String[] { "APPLY_STALLED", "DEGRADED_GAP", "CONSOLIDATING", "MEMORY_REFUSED",
				"FAILED_CORRUPT", "CLOSED", "SOME_FUTURE_STATE" }) {
			assertEquals(LmdbNativeRegimeKey.Phase.TRANSITIONAL_COLD, LmdbNativeRegimeTracker.mapPhase(cold, true));
		}
	}

	@Test
	void aNullContextDegradesToTheSingleSteadyRegime() {
		LmdbNativeRegimeTracker tracker = new LmdbNativeRegimeTracker(null);
		assertEquals(LmdbNativeRegimeKey.STEADY, tracker.current());
		assertEquals(0L, tracker.epoch());
		tracker.forceEpochBump();
		assertEquals(1L, tracker.epoch());
		assertEquals(LmdbNativeRegimeKey.STEADY, tracker.current());
	}

	@Test
	void regimeChangesBumpTheEpochMonotonically() {
		AtomicReference<String> phase = new AtomicReference<>("BUILDING");
		AtomicLong adjacencyEpoch = new AtomicLong();
		AtomicLong dataGeneration = new AtomicLong();
		LmdbNativeCostModelContext context = new LmdbNativeCostModelContext(Path.of("unused"),
				UUID.nameUUIDFromBytes(new byte[] { 1 }), adjacencyEpoch::get, phase::get, dataGeneration::get,
				() -> 0L);
		LmdbNativeRegimeTracker tracker = new LmdbNativeRegimeTracker(context);

		LmdbNativeRegimeKey first = tracker.current();
		assertEquals(LmdbNativeRegimeKey.Phase.BUILDING, first.phase());
		long epochAfterFirst = tracker.epoch();
		assertEquals(first, tracker.current());
		assertEquals(epochAfterFirst, tracker.epoch(), "an unchanged regime must not advance the epoch");

		phase.set("ACTIVE");
		adjacencyEpoch.incrementAndGet();
		LmdbNativeRegimeKey second = tracker.current();
		assertTrue(tracker.epoch() > epochAfterFirst, "a regime change must bump the epoch");
		long epochAfterSecond = tracker.epoch();

		dataGeneration.incrementAndGet();
		LmdbNativeRegimeKey third = tracker.current();
		assertTrue(tracker.epoch() > epochAfterSecond, "a data-generation change is a regime change");
		assertTrue(!second.equals(third));
	}
}
